        UiKey::MouseScrollUp { column, row } => {
            self.pending = None;
            self.handle_mouse_scroll(column, row, true);
            return Vec::new();
        }
        UiKey::MouseScrollDown { column, row } => {
            self.pending = None;
            self.handle_mouse_scroll(column, row, false);
            return Vec::new();
        }
        _ => {}
