+fn selected_text(selection: &VisualSelection, lines: &[String], force_line: bool) -> String {
+    selection_ranges(selection, lines, force_line)
+        .into_iter()
+        .map(|(row, start, end)| char_slice(&lines[row], start, end))
+        .collect::<Vec<_>>()
