+}
+
+fn selection_ranges(
+    selection: &VisualSelection,
+    lines: &[String],
+    force_line: bool,
+) -> Vec<(usize, usize, usize)> {
+    if lines.is_empty() {
+        return Vec::new();
+    }
+
+    let kind = if force_line {
+        VisualKind::Line
+    } else {
+        selection.kind
+    };
+    match kind {
+        VisualKind::Character => character_selection_ranges(selection, lines),
+        VisualKind::Line => line_selection_ranges(selection, lines),
+        VisualKind::Block => block_selection_ranges(selection, lines),
+    }
+}
+
+fn character_selection_ranges(selection: &VisualSelection, lines: &[String]) -> Vec<(usize, usize, usize)> {
+    let (start, end) = ordered_points(selection, lines);
+    let mut ranges = Vec::new();
+    for row in start.row..=end.row {
+        let line_len = line_char_count(&lines[row]);
+        if line_len == 0 {
+            continue;
+        }
+        let (range_start, range_end) = if start.row == end.row {
+            (
+                start.column.min(line_len.saturating_sub(1)),
+                end.column.min(line_len.saturating_sub(1)).saturating_add(1),
+            )
+        } else if row == start.row {
+            (start.column.min(line_len), line_len)
+        } else if row == end.row {
+            (0, end.column.min(line_len.saturating_sub(1)).saturating_add(1))
+        } else {
+            (0, line_len)
+        };
+        if range_start < range_end {
+            ranges.push((row, range_start, range_end));
+        }
+    }
+    ranges
+}
+
+fn line_selection_ranges(selection: &VisualSelection, lines: &[String]) -> Vec<(usize, usize, usize)> {
+    let start = selection.anchor.row.min(selection.cursor.row).min(lines.len() - 1);
+    let end = selection.anchor.row.max(selection.cursor.row).min(lines.len() - 1);
+    (start..=end)
+        .filter_map(|row| {
+            let line_len = line_char_count(&lines[row]);
+            (line_len > 0).then_some((row, 0, line_len))
+        })
+        .collect()
+}
+
+fn block_selection_ranges(selection: &VisualSelection, lines: &[String]) -> Vec<(usize, usize, usize)> {
+    let start_row = selection.anchor.row.min(selection.cursor.row).min(lines.len() - 1);
+    let end_row = selection.anchor.row.max(selection.cursor.row).min(lines.len() - 1);
+    let start_column = selection.anchor.column.min(selection.cursor.column);
+    let end_column = selection.anchor.column.max(selection.cursor.column);
+
+    (start_row..=end_row)
+        .filter_map(|row| {
+            let line_len = line_char_count(&lines[row]);
+            let range_start = start_column.min(line_len);
+            let range_end = end_column
+                .min(line_len.saturating_sub(1))
+                .saturating_add(1);
+            (range_start < range_end).then_some((row, range_start, range_end))
+        })
+        .collect()
+}
+
+fn ordered_points(selection: &VisualSelection, lines: &[String]) -> (TextPoint, TextPoint) {
+    let max_row = lines.len().saturating_sub(1);
+    let anchor = TextPoint {
+        row: selection.anchor.row.min(max_row),
+        column: selection.anchor.column,
+    };
+    let cursor = TextPoint {
+        row: selection.cursor.row.min(max_row),
+        column: selection.cursor.column,
+    };
+    if anchor.row < cursor.row || (anchor.row == cursor.row && anchor.column <= cursor.column) {
+        (anchor, cursor)
+    } else {
+        (cursor, anchor)
+    }
+}
+
+fn line_char_count(line: &str) -> usize {
+    line.chars().count()
+}
+
+fn char_slice(line: &str, start: usize, end: usize) -> String {
+    line.chars()
+        .skip(start)
+        .take(end.saturating_sub(start))
+        .collect()
+}
